#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

    /// Reverses the elements of the input slice `a` and returns
    /// a fresh `Vec<i32>` containing those elements in reverse order.
    ///
    /// - No preconditions on `a`.
    /// - The result has the same length as `a`.
    /// - For all valid indices `i`, `result[i] == a[a.len() - 1 - i]`.
    fn reverse(a: &[i32]) -> (result: Vec<i32>)
        ensures
            // Lengths agree
            result.len() == a.len(),
        ensures
            // Element-wise reversal property
            forall |i: usize| i < a.len() ==> result[i] == a[a.len() - 1 - i],
    {
        let n = a.len();
        // Allocate a vector with enough capacity up front
        let mut result = Vec::with_capacity(n);
        let mut i: usize = 0;

        // Build up `result` by pushing a[n-1], a[n-2], ..., a[0]
        while i < n
            invariant i <= n
            invariant result.len() == i
            invariant forall |j: usize|
                j < i ==> result[j] == a[n - 1 - j]
            decreases n - i
        {
            let x = a[n - 1 - i];
            result.push(x);
            i += 1;
        }

        result
    }

}